namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Hydraulic Press", "Building A - Floor 1", new DateTime(2026, 3, 15)),
            new(2, "CNC Lathe", "Building A - Floor 2", new DateTime(2026, 5, 22)),
            new(3, "Forklift #7", "Warehouse B", new DateTime(2026, 6, 10)),
            new(4, "Conveyor Belt Motor", "Building C - Line 3", new DateTime(2026, 1, 8)),
            new(5, "Industrial Compressor", "Building A - Basement", new DateTime(2025, 11, 30)),
            new(6, "Welding Station #2", "Building D - Bay 4", new DateTime(2026, 4, 18)),
            new(7, "Overhead Crane", "Warehouse B", new DateTime(2026, 2, 25)),
            new(8, "Packaging Robot Arm", "Building C - Line 1", new DateTime(2026, 6, 1)),
        };
    }
}

@page "/inventory"
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@attribute [StreamRendering]

<PageTitle>Equipment Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await EquipmentService.GetEquipmentAsync();
    }
}

